// Activity selection: sort by end, take every interval that starts after the last end.
function maxNonOverlapping(intervals) {
  const sorted = [...intervals].sort((a, b) => a[1] - b[1]);
  let count = 0, lastEnd = -Infinity;
  for (const [s, e] of sorted) {
    if (s >= lastEnd) { count++; lastEnd = e; }
  }
  return count;
}

// LeetCode 881 Boats to Save People: pair the heaviest with the lightest if possible.
function numRescueBoats(people, limit) {
  people.sort((a, b) => a - b);
  let i = 0, j = people.length - 1, boats = 0;
  while (i <= j) {
    if (people[i] + people[j] <= limit) i++;   // lightest rides along
    j--;                                        // heaviest always leaves
    boats++;
  }
  return boats;
}

from itertools import combinations

def max_non_overlapping(intervals):
    """Activity selection: earliest end first. O(n log n)."""
    count, last_end = 0, float("-inf")
    for start, end in sorted(intervals, key=lambda iv: iv[1]):
        if start >= last_end:                 # touching endpoints allowed
            count += 1
            last_end = end
    return count

def brute_force(intervals):
    """Exponential checker for small inputs: use it to test a greedy rule."""
    for k in range(len(intervals), 0, -1):
        for combo in combinations(sorted(intervals), k):
            if all(combo[i][1] <= combo[i + 1][0] for i in range(k - 1)):
                return k
    return 0

