// Activity selection, O(n log n).
static int maxNonOverlapping(int[][] intervals) {
    int[][] iv = intervals.clone();
    Arrays.sort(iv, (a, b) -> Integer.compare(a[1], b[1]));
    int count = 0;
    long lastEnd = Long.MIN_VALUE;
    for (int[] x : iv) {
        if (x[0] >= lastEnd) { count++; lastEnd = x[1]; }
    }
    return count;
}

// LeetCode 55 Jump Game: O(n), O(1).
function canJump(nums) {
  let farthest = 0;
  for (let i = 0; i < nums.length; i++) {
    if (i > farthest) return false;
    farthest = Math.max(farthest, i + nums[i]);
  }
  return true;
}

// LeetCode 45 Jump Game II: BFS layers as ranges.
function jump(nums) {
  let jumps = 0, currentEnd = 0, farthest = 0;
  for (let i = 0; i < nums.length - 1; i++) {   // stop before the last index
    farthest = Math.max(farthest, i + nums[i]);
    if (i === currentEnd) { jumps++; currentEnd = farthest; }
  }
  return jumps;
}

// LeetCode 134 Gas Station.
function canCompleteCircuit(gas, cost) {
  let total = 0, tank = 0, start = 0;
  for (let i = 0; i < gas.length; i++) {
    const d = gas[i] - cost[i];
    total += d;
    tank += d;
    if (tank < 0) { start = i + 1; tank = 0; }  // no start in [start, i] works
  }
  return total >= 0 ? start : -1;
}

// LeetCode 763 Partition Labels.
function partitionLabels(s) {
  const last = {};
  for (let i = 0; i < s.length; i++) last[s[i]] = i;
  const sizes = [];
  let start = 0, end = 0;
  for (let i = 0; i < s.length; i++) {
    end = Math.max(end, last[s[i]]);
    if (i === end) { sizes.push(end - start + 1); start = i + 1; }
  }
  return sizes;
}

from collections import Counter

def can_complete_circuit(gas, cost):
    if sum(gas) < sum(cost):
        return -1
    tank = start = 0
    for i in range(len(gas)):
        tank += gas[i] - cost[i]
        if tank < 0:
            start, tank = i + 1, 0
    return start

def is_n_straight_hand(hand, w):
    """LeetCode 846: the smallest remaining card must start a group. O(n log n)."""
    if len(hand) % w:
        return False
    count = Counter(hand)
    for card in sorted(count):
        need = count[card]
        if need == 0:
            continue
        for v in range(card, card + w):
            if count[v] < need:
                return False
            count[v] -= need
    return True

def check_valid_string(s):
    """LeetCode 678: track the range [lo, hi] of possible open brackets."""
    lo = hi = 0
    for ch in s:
        if ch == "(":
            lo, hi = lo + 1, hi + 1
        elif ch == ")":
            lo, hi = lo - 1, hi - 1
        else:
            lo, hi = lo - 1, hi + 1
        if hi < 0:
            return False
        lo = max(lo, 0)
    return lo == 0

def candy(ratings):
    """LeetCode 135: two passes, take the max."""
    n = len(ratings)
    c = [1] * n
    for i in range(1, n):
        if ratings[i] > ratings[i - 1]:
            c[i] = c[i - 1] + 1
    for i in range(n - 2, -1, -1):
        if ratings[i] > ratings[i + 1]:
            c[i] = max(c[i], c[i + 1] + 1)
    return sum(c)

// LeetCode 45 Jump Game II.
static int jump(int[] nums) {
    int jumps = 0, currentEnd = 0, farthest = 0;
    for (int i = 0; i < nums.length - 1; i++) {
        farthest = Math.max(farthest, i + nums[i]);
        if (i == currentEnd) { jumps++; currentEnd = farthest; }
    }
    return jumps;
}

// LeetCode 134 Gas Station.
static int canCompleteCircuit(int[] gas, int[] cost) {
    int total = 0, tank = 0, start = 0;
    for (int i = 0; i < gas.length; i++) {
        int d = gas[i] - cost[i];
        total += d;
        tank += d;
        if (tank < 0) { start = i + 1; tank = 0; }
    }
    return total >= 0 ? start : -1;
}

// LeetCode 55 Jump Game.
bool canJump(const vector<int>& nums) {
    int farthest = 0;
    for (int i = 0; i < (int)nums.size(); i++) {
        if (i > farthest) return false;
        farthest = max(farthest, i + nums[i]);
    }
    return true;
}

// LeetCode 846 Hand of Straights with an ordered map.
bool isNStraightHand(const vector<int>& hand, int w) {
    if (hand.size() % w) return false;
    map<int, int> count;
    for (int c : hand) count[c]++;
    for (auto& [card, need] : count) {
        if (need == 0) continue;
        int n = need;
        for (int v = card; v < card + w; v++) {
            auto it = count.find(v);
            if (it == count.end() || it->second < n) return false;
            it->second -= n;
        }
    }
    return true;
}

// LeetCode 56 Merge Intervals: sort by start, extend the last merged end.
function merge(intervals) {
  intervals.sort((a, b) => a[0] - b[0]);
  const res = [];
  for (const [s, e] of intervals) {
    const last = res[res.length - 1];
    if (last && s <= last[1]) last[1] = Math.max(last[1], e);  // max handles nesting
    else res.push([s, e]);
  }
  return res;
}

// LeetCode 57 Insert Interval: three phases, O(n).
function insert(intervals, [ns, ne]) {
  const res = [];
  let i = 0;
  while (i < intervals.length && intervals[i][1] < ns) res.push(intervals[i++]);
  while (i < intervals.length && intervals[i][0] <= ne) {
    ns = Math.min(ns, intervals[i][0]);
    ne = Math.max(ne, intervals[i][1]);
    i++;
  }
  res.push([ns, ne]);
  while (i < intervals.length) res.push(intervals[i++]);
  return res;
}

// LeetCode 435 Non-overlapping Intervals: sort by end, keep the most, remove the rest.
function eraseOverlapIntervals(intervals) {
  intervals.sort((a, b) => a[1] - b[1]);
  let kept = 0, lastEnd = -Infinity;
  for (const [s, e] of intervals) if (s >= lastEnd) { kept++; lastEnd = e; }
  return intervals.length - kept;
}

def merge(intervals):
    res = []
    for s, e in sorted(intervals):
        if res and s <= res[-1][1]:
            res[-1][1] = max(res[-1][1], e)
        else:
            res.append([s, e])
    return res

def find_min_arrow_shots(points):
    """LeetCode 452: sort by end, shoot at the end, skip balloons containing it."""
    arrows, arrow_x = 0, float("-inf")
    for s, e in sorted(points, key=lambda p: p[1]):
        if s > arrow_x:                 # touching counts as burst
            arrows += 1
            arrow_x = e
    return arrows

def interval_intersection(a, b):
    """LeetCode 986: two pointers; advance the interval that ends first."""
    i = j = 0
    res = []
    while i < len(a) and j < len(b):
        lo = max(a[i][0], b[j][0])
        hi = min(a[i][1], b[j][1])
        if lo <= hi:
            res.append([lo, hi])
        if a[i][1] < b[j][1]:
            i += 1
        else:
            j += 1
    return res

def remove_covered_intervals(intervals):
    """LeetCode 1288: start ascending, end descending, track max end."""
    count, max_end = 0, -1
    for s, e in sorted(intervals, key=lambda iv: (iv[0], -iv[1])):
        if e > max_end:
            count += 1
            max_end = e
    return count

// LeetCode 56 Merge Intervals.
static int[][] merge(int[][] intervals) {
    Arrays.sort(intervals, (a, b) -> Integer.compare(a[0], b[0]));   // no overflow
    List<int[]> res = new ArrayList<>();
    for (int[] iv : intervals) {
        if (!res.isEmpty() && iv[0] <= res.get(res.size() - 1)[1]) {
            int[] last = res.get(res.size() - 1);
            last[1] = Math.max(last[1], iv[1]);
        } else {
            res.add(new int[]{iv[0], iv[1]});
        }
    }
    return res.toArray(new int[0][]);
}

// LeetCode 435 Non-overlapping Intervals.
int eraseOverlapIntervals(vector<vector<int>>& iv) {
    sort(iv.begin(), iv.end(), [](const auto& a, const auto& b) { return a[1] < b[1]; });
    int kept = 0;
    long long lastEnd = LLONG_MIN;
    for (auto& x : iv)
        if (x[0] >= lastEnd) { kept++; lastEnd = x[1]; }
    return (int)iv.size() - kept;
}

// Minimum meeting rooms with two sorted arrays (a compact sweep line).
function minMeetingRooms(intervals) {
  const starts = intervals.map((x) => x[0]).sort((a, b) => a - b);
  const ends = intervals.map((x) => x[1]).sort((a, b) => a - b);
  let rooms = 0, peak = 0, j = 0;
  for (let i = 0; i < starts.length; i++) {
    while (j < ends.length && ends[j] <= starts[i]) { j++; rooms--; }  // ends first on ties
    rooms++;
    peak = Math.max(peak, rooms);
  }
  return peak;
}

// LeetCode 729 My Calendar I with a sorted array + binary search.
// Insertion is O(n) because of the splice; a balanced tree makes it O(log n).
class MyCalendar {
  constructor() { this.b = []; }               // sorted by start, non-overlapping
  book(start, end) {
    let lo = 0, hi = this.b.length;
    while (lo < hi) { const m = (lo + hi) >> 1; this.b[m][0] < start ? (lo = m + 1) : (hi = m); }
    if (lo > 0 && this.b[lo - 1][1] > start) return false;            // previous overlaps
    if (lo < this.b.length && this.b[lo][0] < end) return false;      // next overlaps
    this.b.splice(lo, 0, [start, end]);
    return true;
  }
}

import heapq

def min_meeting_rooms(intervals):
    """Sweep line over half-open [start, end). Ends sort before starts at equal times."""
    events = []
    for s, e in intervals:
        events.append((s, 1))
        events.append((e, -1))
    events.sort()                            # (t, -1) < (t, 1): ends first
    rooms = peak = 0
    for _, delta in events:
        rooms += delta
        peak = max(peak, rooms)
    return peak

def car_pooling(trips, capacity):
    """LeetCode 1094 with a difference array (locations are 0..1000)."""
    diff = [0] * 1001
    for passengers, start, end in trips:
        diff[start] += passengers
        diff[end] -= passengers
    load = 0
    for d in diff:
        load += d
        if load > capacity:
            return False
    return True

def most_booked(n, meetings):
    """LeetCode 2402 Meeting Rooms III: free rooms by number, busy rooms by (end, room)."""
    free = list(range(n))
    busy = []                                # (end_time, room)
    count = [0] * n
    for start, end in sorted(meetings):
        while busy and busy[0][0] <= start:
            _, room = heapq.heappop(busy)
            heapq.heappush(free, room)
        if free:
            room = heapq.heappop(free)
            heapq.heappush(busy, (end, room))
        else:
            t, room = heapq.heappop(busy)    # wait for the earliest-ending room
            heapq.heappush(busy, (t + end - start, room))
        count[room] += 1
    return count.index(max(count))

def min_interval(intervals, queries):
    """LeetCode 1851: sort queries, sweep, heap of (length, end)."""
    intervals.sort()
    ans, heap, i = {}, [], 0
    for q in sorted(set(queries)):
        while i < len(intervals) and intervals[i][0] <= q:
            l, r = intervals[i]
            heapq.heappush(heap, (r - l + 1, r))
            i += 1
        while heap and heap[0][1] < q:
            heapq.heappop(heap)
        ans[q] = heap[0][0] if heap else -1
    return [ans[q] for q in queries]

// LeetCode 729 My Calendar I with a TreeMap: O(log n) per booking.
class MyCalendar {
    private final TreeMap<Integer, Integer> cal = new TreeMap<>();   // start -> end

    public boolean book(int start, int end) {
        Map.Entry<Integer, Integer> prev = cal.floorEntry(start);
        Map.Entry<Integer, Integer> next = cal.ceilingEntry(start);
        if (prev != null && prev.getValue() > start) return false;
        if (next != null && next.getKey() < end) return false;
        cal.put(start, end);
        return true;
    }
}

// Minimum meeting rooms with a min-heap of end times.
static int minMeetingRooms(int[][] intervals) {
    Arrays.sort(intervals, (a, b) -> Integer.compare(a[0], b[0]));
    PriorityQueue<Integer> ends = new PriorityQueue<>();
    int peak = 0;
    for (int[] m : intervals) {
        while (!ends.isEmpty() && ends.peek() <= m[0]) ends.poll();
        ends.add(m[1]);
        peak = Math.max(peak, ends.size());
    }
    return peak;
}
